mapper.select:
SELECT a.id, a.title, a.summary, a.cover_image, a.views, a.likes, a.favorites, a.comments_count, a.is_top, a.is_recommend, a.published_time, a.create_time, u.username AS author_name, u.avatar AS author_avatar, c.name AS category_name, STRING_AGG(t.name, ',') AS tags FROM articles a LEFT JOIN users u ON a.create_by = u.id LEFT JOIN categories c ON a.category_id = c.id LEFT JOIN article_tags at ON a.id = at.article_id LEFT JOIN tags t ON at.tag_id = t.id WHERE a.deleted = 0
AND a.status = #{status}
GROUP BY a.id, u.username, u.avatar, c.name ORDER BY a.is_top DESC, a.published_time DESC, a.create_time DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT a.id, a.title, a.summary, a.cover_image, a.views, a.likes, a.favorites, a.comments_count, a.is_top, a.is_recommend, a.published_time, a.create_time, u.username AS author_name, u.avatar AS author_avatar, c.name AS category_name, STRING_AGG(t.name, ',') AS tags FROM articles a LEFT JOIN users u ON a.create_by = u.id LEFT JOIN categories c ON a.category_id = c.id LEFT JOIN article_tags at ON a.id = at.article_id LEFT JOIN tags t ON at.tag_id = t.id WHERE a.deleted = 0
AND a.status = #{status}
AND ( a.title ILIKE CONCAT('%', #{keyword}, '%') OR a.summary ILIKE CONCAT('%', #{keyword}, '%') OR a.content ILIKE CONCAT('%', #{keyword}, '%') )
GROUP BY a.id, u.username, u.avatar, c.name ORDER BY a.is_top DESC, a.create_time DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(DISTINCT a.id) FROM articles a LEFT JOIN users u ON a.create_by = u.id LEFT JOIN categories c ON a.category_id = c.id LEFT JOIN article_tags at ON a.id = at.article_id LEFT JOIN tags t ON at.tag_id = t.id WHERE a.deleted = 0
AND a.status = #{status}
AND ( a.title ILIKE CONCAT('%', #{keyword}, '%') OR a.summary ILIKE CONCAT('%', #{keyword}, '%') OR a.content ILIKE CONCAT('%', #{keyword}, '%') )
